  // Provider summaries contain empty hourly arrays without reading that dimension.
  const read=results.filter(r=>(!ids.size||ids.has(r.platform?.id))&&Array.isArray(r.groups?.hourly)&&(full(r)||r.groups.hourly.length>0));
